const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{position:relative;width:100%;height:100%;min-width:0;min-height:0;overflow:hidden;color:var(--ink);background:transparent;font-size:14px;line-height:1.25}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;margin:0;cursor:pointer;-webkit-tap-highlight-color:transparent;touch-action:manipulation;user-select:none}\n.card button:focus-visible{outline:3px solid var(--accent);outline-offset:2px}\n.card svg{display:block;width:100%;height:100%}\n\n.wrap{width:100%;height:100%;padding:8px;display:grid;gap:8px;grid-template-columns:minmax(0,1fr);min-width:0;min-height:0}\n\n/* \u6700\u8fd1\u4e00\u6b21\u8bb0\u5f55 */\n.hero{display:flex;align-items:stretch;gap:6px;min-width:0;min-height:0;padding:6px 6px 6px 12px;border-radius:16px;background:var(--accent);color:var(--on-accent)}\n.hero.flash{animation:pop .45s ease-out}\n@keyframes pop{0%{transform:scale(.95)}55%{transform:scale(1.03)}100%{transform:scale(1)}}\n@media (prefers-reduced-motion:reduce){.hero.flash{animation:none}}\n.hero-main{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;gap:1px;padding:0;border:0;background:transparent;color:inherit;text-align:left}\n.hero-top{display:flex;align-items:center;gap:2px;max-width:100%;min-width:0}\n.hero-rel{min-width:0;font-size:11px;opacity:.92;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.hero-chev{flex:none;width:12px;height:12px;opacity:.8}\n.hero-what{display:flex;align-items:center;gap:6px;max-width:100%;min-width:0}\n.hero-kind{display:flex;align-items:center;gap:6px;min-width:0}\n.hero-ico{flex:none;width:22px;height:22px}\n.hero-name{min-width:0;font-size:15px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.hero-time{flex:none;font-size:19px;font-weight:800;font-variant-numeric:tabular-nums;letter-spacing:.2px;white-space:nowrap}\n.hero-sleep{max-width:100%;font-size:11px;opacity:.92;overflow:hidden;text-overflow:ellipsis}\n.hero-sleep:empty{display:none}\n.undo{flex:none;width:44px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;padding:0;border-radius:12px;border:1.5px solid var(--on-accent);background:transparent;color:var(--on-accent);font-size:11px;font-weight:700}\n.undo-ico{display:block;width:18px;height:18px}\n.undo:active:not(:disabled){background:var(--on-accent);color:var(--accent)}\n.undo:disabled{opacity:.45;cursor:default}\n\n/* \u56db\u4e2a\u8bb0\u5f55\u6309\u94ae */\n.acts{display:grid;gap:8px;min-width:0;min-height:0;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(2,minmax(0,1fr))}\n.act{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-width:0;min-height:0;padding:3px;border-radius:16px;border:1.5px solid var(--line);background:var(--panel-paper);color:var(--ink);transition:transform .08s ease,background .08s ease}\n.act:active{transform:scale(.96);background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.act-top{display:flex;align-items:center;justify-content:center;gap:4px;min-width:0}\n.act-ico{display:block;flex:none;width:18px;height:18px;color:var(--accent)}\n.act-sleep .act-ico,.act-wake .act-ico{color:var(--accent-alt)}\n.act:active .act-ico{color:var(--on-accent)}\n.act-lbl{font-size:15px;font-weight:800;line-height:1.1;white-space:nowrap}\n.act-sub{max-width:100%;font-size:10.5px;line-height:1.1;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.act:active .act-sub{color:var(--on-accent)}\n\n/* \u4eca\u5929\uff08\u5927\u5361\uff09\u4e0e\u5386\u53f2 */\n.today{display:flex;flex-direction:column;min-width:0;min-height:0;overflow:hidden;border-radius:14px;border:1px solid var(--line);background:var(--panel-paper)}\n.today-head{flex:none;display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:38px;padding:0 4px 0 12px;border-bottom:1px solid var(--line)}\n.today-l{flex:1;min-width:0;display:flex;align-items:baseline;gap:8px;overflow:hidden}\n.today-t{flex:none;font-size:13px;font-weight:800}\n.today-s{min-width:0;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.link{flex:none;display:flex;align-items:center;gap:2px;height:36px;padding:0 6px 0 8px;border:0;background:transparent;color:var(--accent);font-size:13px;font-weight:700}\n.link svg{width:14px;height:14px}\n.list,.hist-list{flex:1;min-width:0;min-height:0;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain}\n.hist{width:100%;height:100%;padding:8px;display:flex;flex-direction:column;gap:8px;min-width:0;min-height:0}\n.hist-head{flex:none;display:flex;align-items:center;gap:8px}\n.back{flex:none;display:flex;align-items:center;gap:2px;height:44px;padding:0 12px 0 6px;border-radius:14px;border:1.5px solid var(--line);background:var(--panel-paper);color:var(--ink);font-size:15px;font-weight:700}\n.back svg{width:20px;height:20px}\n.hist-title{flex:1;min-width:0;font-size:16px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.hist-count{flex:none;font-size:12px;color:var(--muted)}\n.hist-list{border-radius:14px;border:1px solid var(--line);background:var(--panel-paper)}\n.day{position:sticky;top:0;z-index:1;display:flex;flex-wrap:wrap;align-items:baseline;gap:0 8px;padding:6px 10px 4px;background:var(--soft);color:var(--ink)}\n.day-l{font-size:13px;font-weight:800}\n.day-s{font-size:11px;color:var(--muted)}\n.row{display:flex;align-items:center;gap:8px;min-height:40px;padding:2px 4px 2px 10px;border-top:1px solid var(--line)}\n.day+.row{border-top:0}\n.row-ico{flex:none;width:20px;height:20px;color:var(--accent)}\n.row-name{flex:1;min-width:0;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.row-time{flex:none;font-weight:700;font-variant-numeric:tabular-nums}\n.row-del{flex:none;min-width:36px;height:34px;display:flex;align-items:center;justify-content:center;padding:0 6px;border-radius:10px;border:1px solid var(--line);background:transparent;color:var(--muted);font-size:12px;white-space:nowrap}\n.row-del svg{width:14px;height:14px}\n.row-del.confirm{border-color:var(--accent);background:var(--accent);color:var(--on-accent);font-weight:700}\n.empty-tip{padding:16px 12px;text-align:center;font-size:13px;color:var(--muted)}\n\n/* 3x3\uff1a\u6700\u8fd1\u8bb0\u5f55\u6a2a\u6761 + 2x2 \u6309\u94ae */\n.card[data-size=\"3x3\"] .wrap{grid-template-rows:auto minmax(0,1fr)}\n.card[data-size=\"3x3\"] .hero-ico,\n.card[data-size=\"3x3\"] .hero-sleep{display:none}\n.card[data-size=\"3x3\"] .hero-name{font-size:15px}\n.card[data-size=\"3x3\"] .hero-time{font-size:19px}\n.card[data-size=\"3x3\"] .act{padding:2px}\n.card[data-size=\"3x3\"] .back{height:40px;padding:0 10px 0 4px;font-size:13px}\n.card[data-size=\"3x3\"] .hist-title{font-size:14px}\n.card[data-size=\"3x3\"] .hist-count{display:none}\n.card[data-size=\"3x3\"] .day-s{font-size:10px}\n\n/* 3x6\uff1a\u6700\u8fd1\u8bb0\u5f55\u6a2a\u6761 + \u56db\u4e2a\u6574\u884c\u5927\u6309\u94ae */\n.card[data-size=\"3x6\"] .wrap{grid-template-rows:auto minmax(0,1fr)}\n.card[data-size=\"3x6\"] .hero{padding:8px 6px 8px 12px}\n.card[data-size=\"3x6\"] .hero-ico{display:none}\n.card[data-size=\"3x6\"] .hero-sleep{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;white-space:normal;font-size:11px}\n.card[data-size=\"3x6\"] .undo{width:48px}\n.card[data-size=\"3x6\"] .acts{grid-template-columns:minmax(0,1fr);grid-template-rows:repeat(4,minmax(0,1fr))}\n\n/* 6x3\uff1a\u5de6\u4fa7\u6700\u8fd1\u8bb0\u5f55 + \u64a4\u56de\uff0c\u53f3\u4fa7 2x2 \u5927\u6309\u94ae */\n.card[data-size=\"6x3\"] .wrap{grid-template-columns:150px minmax(0,1fr);grid-template-rows:minmax(0,1fr)}\n.card[data-size=\"6x3\"] .hero{flex-direction:column;gap:8px;padding:8px 8px 8px 12px}\n.card[data-size=\"6x3\"] .hero-main{flex:1;justify-content:flex-start;gap:2px;overflow:hidden}\n.card[data-size=\"6x3\"] .hero-rel{font-size:12px}\n.card[data-size=\"6x3\"] .hero-what{flex-direction:column;align-items:flex-start;gap:0}\n.card[data-size=\"6x3\"] .hero-ico{width:20px;height:20px}\n.card[data-size=\"6x3\"] .hero-name{font-size:17px}\n.card[data-size=\"6x3\"] .hero-time{font-size:30px;line-height:1.1}\n.card[data-size=\"6x3\"] .hero-sleep{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;white-space:normal;font-size:12px}\n.card[data-size=\"6x3\"] .undo{flex:none;width:auto;height:42px;flex-direction:row;gap:6px;font-size:14px}\n.card[data-size=\"6x3\"] .undo-ico{width:18px;height:18px}\n.card[data-size=\"6x3\"] .act{gap:4px}\n.card[data-size=\"6x3\"] .act-top{flex-direction:column;gap:4px}\n.card[data-size=\"6x3\"] .act-ico{width:30px;height:30px}\n.card[data-size=\"6x3\"] .act-lbl{font-size:18px}\n.card[data-size=\"6x3\"] .act-sub{font-size:11px}\n\n/* 6x6\uff1a\u6700\u8fd1\u8bb0\u5f55 + 2x2 \u6a2a\u5411\u5927\u6309\u94ae + \u4eca\u5929\u7684\u8bb0\u5f55\u5217\u8868 */\n.card[data-size=\"6x6\"] .wrap{grid-template-rows:auto minmax(0,1.25fr) minmax(0,1fr)}\n.card[data-size=\"6x6\"] .hero{gap:8px;padding:8px 8px 8px 16px}\n.card[data-size=\"6x6\"] .hero-rel{font-size:13px}\n.card[data-size=\"6x6\"] .hero-ico{width:28px;height:28px}\n.card[data-size=\"6x6\"] .hero-name{font-size:22px}\n.card[data-size=\"6x6\"] .hero-time{font-size:34px;line-height:1.1}\n.card[data-size=\"6x6\"] .hero-sleep{font-size:13px;white-space:nowrap}\n.card[data-size=\"6x6\"] .undo{width:68px;min-height:56px;font-size:13px}\n.card[data-size=\"6x6\"] .undo-ico{width:22px;height:22px}\n.card[data-size=\"6x6\"] .row{min-height:36px}\n\n/* 3x6 \u4e0e 6x6\uff1a\u6309\u94ae\u56fe\u6807\u5728\u5de6\u3001\u540d\u79f0\u4e0e\u4e0a\u6b21\u65f6\u95f4\u5728\u53f3 */\n.card[data-size=\"3x6\"] .act,\n.card[data-size=\"6x6\"] .act{display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-areas:\"ico lbl\" \"ico sub\";column-gap:12px;row-gap:2px;align-content:center;justify-items:start;padding:6px 14px;text-align:left}\n.card[data-size=\"3x6\"] .act-top,\n.card[data-size=\"6x6\"] .act-top{display:contents}\n.card[data-size=\"3x6\"] .act-ico,\n.card[data-size=\"6x6\"] .act-ico{grid-area:ico;align-self:center;width:36px;height:36px}\n.card[data-size=\"3x6\"] .act-lbl,\n.card[data-size=\"6x6\"] .act-lbl{grid-area:lbl;align-self:end;font-size:21px}\n.card[data-size=\"3x6\"] .act-sub,\n.card[data-size=\"6x6\"] .act-sub{grid-area:sub;align-self:start;font-size:12px}\n.card[data-size=\"6x6\"] .act-ico{width:34px;height:34px}\n.card[data-size=\"6x6\"] .act-lbl{font-size:20px}\n";
var TYPES=[
  {key:'feed',label:'喝奶',icon:'bottle'},
  {key:'sleep',label:'入睡',icon:'moon'},
  {key:'wake',label:'睡醒',icon:'sun'},
  {key:'diaper',label:'换尿布',icon:'diaper'}
];
var TYPE_MAP={};
TYPES.forEach(function(t){TYPE_MAP[t.key]=t;});

var ICONS={
  bottle:[['path',{d:'M10 7V5.5a2 2 0 0 1 4 0V7'}],['path',{d:'M7 7h10'}],['rect',{x:8,y:7,width:8,height:14,rx:2}],['path',{d:'M8 12h3M8 16h3'}]],
  moon:[['path',{d:'M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z'}]],
  sun:[['circle',{cx:12,cy:12,r:4}],['path',{d:'M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41'}]],
  diaper:[['path',{d:'M3 5h18l-1 6c-1.7 1-2.7 3-3 6H7c-.3-3-1.3-5-3-6z'}],['path',{d:'M6.5 8.5h2M15.5 8.5h2'}]],
  undo:[['path',{d:'M9 14 4 9l5-5'}],['path',{d:'M4 9h10.5a5.5 5.5 0 0 1 5.5 5.5a5.5 5.5 0 0 1-5.5 5.5H11'}]],
  right:[['path',{d:'m9 18 6-6-6-6'}]],
  left:[['path',{d:'m15 18-6-6 6-6'}]],
  x:[['path',{d:'M18 6 6 18M6 6l12 12'}]]
};

function svgIcon(name){
  var NS='http://www.w3.org/2000/svg';
  var s=document.createElementNS(NS,'svg');
  s.setAttribute('viewBox','0 0 24 24');
  s.setAttribute('fill','none');
  s.setAttribute('stroke','currentColor');
  s.setAttribute('stroke-width','2');
  s.setAttribute('stroke-linecap','round');
  s.setAttribute('stroke-linejoin','round');
  s.setAttribute('aria-hidden','true');
  (ICONS[name]||[]).forEach(function(p){
    var n=document.createElementNS(NS,p[0]);
    Object.keys(p[1]).forEach(function(k){n.setAttribute(k,String(p[1][k]));});
    s.appendChild(n);
  });
  return s;
}
function ico(name,cls){
  var w=document.createElement('span');
  w.className=cls||'ico';
  w.appendChild(svgIcon(name));
  return w;
}

function pad2(n){return n<10?'0'+n:''+n;}
function fmtClock(ts){var d=new Date(ts);return pad2(d.getHours())+':'+pad2(d.getMinutes());}
function dayKey(ts){var d=new Date(ts);return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}
function isToday(ts){return dayKey(ts)===dayKey(Date.now());}
function dayLabel(ts){
  var k=dayKey(ts);
  if(k===dayKey(Date.now()))return '今天';
  var n=new Date();
  var y=new Date(n.getFullYear(),n.getMonth(),n.getDate()-1);
  if(k===dayKey(y.getTime()))return '昨天';
  var d=new Date(ts);
  return (d.getMonth()+1)+'月'+d.getDate()+'日';
}
function fmtDur(ms){
  var m=Math.floor(Math.max(0,ms)/60000);
  if(m<1)return '不到1分钟';
  if(m<60)return m+'分钟';
  var h=Math.floor(m/60),mm=m%60;
  if(h<24)return mm?h+'小时'+mm+'分':h+'小时';
  var d=Math.floor(h/24),hh=h%24;
  return hh?d+'天'+hh+'小时':d+'天';
}
function fmtAgo(ms){
  var m=Math.floor(Math.max(0,ms)/60000);
  if(m<1)return '刚刚';
  return fmtDur(ms)+'前';
}
function relLabel(ts){
  var ago=fmtAgo(Date.now()-ts);
  return isToday(ts)?ago:dayLabel(ts)+' · '+ago;
}

function rawRecords(s){return (s&&Array.isArray(s.records))?s.records:[];}
function normRecords(s){
  return rawRecords(s).filter(function(r){
    return r&&TYPE_MAP[r.type]&&typeof r.ts==='number'&&isFinite(r.ts);
  }).slice().sort(function(a,b){return b.ts-a.ts;});
}
function lastOfType(recs,type){
  for(var i=0;i<recs.length;i++){if(recs[i].type===type)return recs[i];}
  return null;
}
function sleepText(recs){
  for(var i=0;i<recs.length;i++){
    var r=recs[i];
    if(r.type==='sleep')return '睡着中 · 已睡 '+fmtDur(Date.now()-r.ts);
    if(r.type==='wake')return '醒着 · 已醒 '+fmtDur(Date.now()-r.ts);
  }
  return '';
}
function groupByDay(recs){
  var groups=[],cur=null;
  recs.forEach(function(r){
    var k=dayKey(r.ts);
    if(!cur||cur.key!==k){cur={key:k,label:dayLabel(r.ts),items:[]};groups.push(cur);}
    cur.items.push(r);
  });
  return groups;
}
function daySummary(items){
  var c={};
  items.forEach(function(r){c[r.type]=(c[r.type]||0)+1;});
  return TYPES.filter(function(t){return c[t.key];}).map(function(t){return t.label+c[t.key];}).join(' · ');
}


function mount(ctx){
  const {root,el,state,ui,update,redraw,uid,size}=ctx;
  const recs=normRecords(state);
  const latest=recs[0]||null;
  const compact=size==='3x3';
  const ticks=[];
  const afterAttach=[];
  const dayAtMount=dayKey(Date.now());

  function tickNode(node,fn){
    node.textContent=fn();
    ticks.push([node,fn]);
    return node;
  }
  function runTicks(){
    ticks.forEach(function(p){
      const v=p[1]();
      if(p[0].textContent!==v)p[0].textContent=v;
    });
  }
  function keepScroll(node,key){
    node.addEventListener('scroll',function(){ui[key]=node.scrollTop;});
    afterAttach.push(function(){if(ui[key])node.scrollTop=ui[key];});
  }

  function logEvent(type){
    const rec={id:uid(),type:type,ts:Date.now()};
    ui.flash=rec.id;
    ui.note=null;
    ui.confirmDel=null;
    ui.todayScroll=0;
    update(function(s){
      return Object.assign({},s,{records:rawRecords(s).concat([rec])});
    }).catch(function(){ui.flash=null;});
  }
  function undoLast(){
    if(!latest)return;
    const id=latest.id;
    ui.note={text:'已撤回 '+TYPE_MAP[latest.type].label,until:Date.now()+3000};
    ui.flash=null;
    ui.confirmDel=null;
    update(function(s){
      return Object.assign({},s,{records:rawRecords(s).filter(function(r){return r.id!==id;})});
    }).catch(function(){ui.note=null;});
  }
  function delRec(r){
    if(ui.confirmDel!==r.id){
      ui.confirmDel=r.id;
      redraw();
      setTimeout(function(){
        if(ui.confirmDel===r.id){ui.confirmDel=null;redraw();}
      },3000);
      return;
    }
    ui.confirmDel=null;
    update(function(s){
      return Object.assign({},s,{records:rawRecords(s).filter(function(x){return x.id!==r.id;})});
    }).catch(function(){});
  }
  function openHistory(){
    ui.view='history';
    ui.histScroll=0;
    ui.confirmDel=null;
    redraw();
  }
  function closeHistory(){
    ui.view='main';
    ui.confirmDel=null;
    redraw();
  }

  function heroRel(){
    if(ui.note&&Date.now()<ui.note.until)return ui.note.text;
    return latest?relLabel(latest.ts):'最近一次';
  }

  function buildHero(){
    const flash=latest&&ui.flash===latest.id;
    ui.flash=null;
    let what;
    if(latest){
      const t=TYPE_MAP[latest.type];
      what=el('span',{class:'hero-what'},
        el('span',{class:'hero-kind'},ico(t.icon,'hero-ico'),el('span',{class:'hero-name'},t.label)),
        el('span',{class:'hero-time'},fmtClock(latest.ts)));
    }else{
      what=el('span',{class:'hero-what'},
        el('span',{class:'hero-kind'},el('span',{class:'hero-name'},'还没有记录')));
    }
    const top=el('span',{class:'hero-top'},
      tickNode(el('span',{class:'hero-rel'}),heroRel),
      ico('right','hero-chev'));
    const main=el('button',{type:'button',class:'hero-main','aria-label':'最近一次记录，点按查看全部记录',onclick:openHistory},
      top,what,
      tickNode(el('span',{class:'hero-sleep'}),function(){return sleepText(recs);}));
    const undo=el('button',{type:'button',class:'undo',disabled:!latest,
      'aria-label':latest?'撤回最近一条记录：'+TYPE_MAP[latest.type].label+' '+fmtClock(latest.ts):'没有可撤回的记录',
      onclick:undoLast},
      ico('undo','undo-ico'),el('span',{class:'undo-t'},'撤回'));
    return el('div',{class:'hero'+(latest?'':' empty')+(flash?' flash':'')},main,undo);
  }

  function buildActs(){
    const btns=TYPES.map(function(t){
