  }

  function buildMain(){
    const kids=[buildHero(),buildActs()];
    if(size==='6x6')kids.push(buildToday());
    return el('div',{class:'wrap'},...kids);
  }

  root.append(ui.view==='history'?buildHistory():buildMain());
  afterAttach.forEach(function(fn){fn();});

  const timer=setInterval(function(){
    if(dayKey(Date.now())!==dayAtMount){redraw();return;}
    runTicks();
  },1000);
  return function(){clearInterval(timer);};
}

